insert into public.course_lessons (id, subject_id, sort_order, title, steps)
values
  ($q$gh01$q$, $q$greetings-hello$q$, 0, $q$Hello!$q$, $j$[{"id":"rule-1","type":"rule","title":"Polite particles","body":"Thai has polite words added to the end of a question, response, or statement: khráp for men; for women, khâ after statements and answers and khá after questions. They make it sound more polite. They are used with people older than you, or whenever you want to sound polite — for example, when first meeting someone.","source":"Essential Thai (Higbie), p.22"},{"id":"wi-2","type":"wordIntro","word":{"thai":"สวัสดี","roman":"sà-wàt-dii","english":"hello"},"source":"Essential Thai (Higbie), p.22"},{"id":"wi-3","type":"wordIntro","word":{"thai":"ค่ะ","roman":"khâ","english":"polite particle (said by women)"},"source":"Essential Thai (Higbie), p.22"},{"id":"mc-5","type":"translationChoice","thai":"สวัสดีค่ะ","roman":"sà-wàt-dii khâ","options":[{"text":"Good luck.","correct":false},{"text":"Hello. (said by a woman)","correct":true},{"text":"Excuse me.","correct":false},{"text":"Thank you.","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["สวัสดี","ค่ะ"]},{"id":"sp-7","type":"speak","thai":"สวัสดีค่ะ","roman":"sà-wàt-dii khâ","meaning":"Hello. (said by a woman)","source":"Essential Thai (Higbie), p.22","parts":["สวัสดี","ค่ะ"]},{"id":"so-9","type":"sentenceOrder","prompt":"Hello. (said by a woman)","tileUnit":"word","words":{"a":{"roman":"sà-wàt-dii","thai":"สวัสดี"},"b":{"roman":"khâ","thai":"ค่ะ"}},"poolOrder":["b","a"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.22"},{"id":"mc-11","type":"translationChoice","thai":"ค่ะ","roman":"khâ","options":[{"text":"Polite particle (said by a man).","correct":false},{"text":"Thank you.","correct":false},{"text":"Polite particle (said by a woman).","correct":true},{"text":"Hello.","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["ค่ะ"]},{"id":"wi-4","type":"wordIntro","word":{"thai":"ครับ","roman":"khráp","english":"polite particle (said by men)"},"source":"Essential Thai (Higbie), p.22"},{"id":"rp-6","type":"reply","context":[{"speaker":"M","thai":"สวัสดีครับ","parts":["สวัสดี","ครับ"],"roman":"sà-wàt-dii khráp","english":"Hello. (said by a man)"}],"replySpeaker":"F","thai":"สวัสดีค่ะ","roman":"sà-wàt-dii khâ","english":"Hello. (said by a woman)","options":[{"thai":"สวัสดีครับ","roman":"sà-wàt-dii khráp","correct":false},{"thai":"สวัสดีค่ะ","roman":"sà-wàt-dii khâ","correct":true},{"thai":"ครับ","roman":"khráp","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["สวัสดี","ค่ะ"]},{"id":"mc-8","type":"translationChoice","thai":"สวัสดีครับ","roman":"sà-wàt-dii khráp","options":[{"text":"How are you?","correct":false},{"text":"Thank you.","correct":false},{"text":"Good luck.","correct":false},{"text":"Hello. (said by a man)","correct":true}],"source":"Essential Thai (Higbie), p.22","parts":["สวัสดี","ครับ"]},{"id":"sp-10","type":"speak","thai":"สวัสดีครับ","roman":"sà-wàt-dii khráp","meaning":"Hello. (said by a man)","source":"Essential Thai (Higbie), p.22","parts":["สวัสดี","ครับ"]},{"id":"mc-12","type":"translationChoice","thai":"ครับ","roman":"khráp","options":[{"text":"Polite particle (said by a man).","correct":true},{"text":"Polite particle (said by a woman).","correct":false},{"text":"Thank you.","correct":false},{"text":"Hello.","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["ครับ"]},{"id":"wi-13","type":"wordIntro","word":{"thai":"ไป","roman":"pai","english":"go"},"source":"Essential Thai (Higbie), p.22"},{"id":"wi-14","type":"wordIntro","word":{"thai":"ไหน","roman":"nǎi","english":"where"},"source":"Essential Thai (Higbie), p.22"},{"id":"mc-15","type":"translationChoice","thai":"ไปไหน","roman":"pai nǎi","options":[{"text":"Hello.","correct":false},{"text":"Where are you going?","correct":true},{"text":"What's your name?","correct":false},{"text":"Good luck.","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["ไป","ไหน"]},{"id":"so-16","type":"sentenceOrder","prompt":"Where are you going?","tileUnit":"word","words":{"a":{"roman":"pai","thai":"ไป"},"b":{"roman":"nǎi","thai":"ไหน"},"x0":{"thai":"ครับ","roman":"khráp"},"x1":{"thai":"สวัสดี","roman":"sà-wàt-dii"}},"poolOrder":["x0","b","a","x1"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.22"},{"id":"match-17","type":"match","pairs":[{"thai":"สวัสดี","roman":"sà-wàt-dii","english":"hello"},{"thai":"ค่ะ","roman":"khâ","english":"polite particle (said by women)"},{"thai":"ครับ","roman":"khráp","english":"polite particle (said by men)"},{"thai":"ไป","roman":"pai","english":"go"},{"thai":"ไหน","roman":"nǎi","english":"where"}],"source":"Essential Thai (Higbie), p.22"}]$j$::jsonb),
