  ($q$gh03$q$, $q$greetings-hello$q$, 2, $q$Good, or not?$q$, $j$[{"id":"rule-36","type":"rule","title":"Yes/no questions with mái","body":"To make a simple question like \"is it good?\", put mái (high tone) after the word. Answer \"yes\" by repeating the word, or \"no\" by putting mâi (falling tone) before it.","source":"Essential Thai (Higbie), p.23"},{"id":"wi-37","type":"wordIntro","word":{"thai":"ดี","roman":"dii","english":"good"},"source":"Essential Thai (Higbie), p.23"},{"id":"mc-48","type":"translationChoice","thai":"ดี","roman":"dii","options":[{"text":"question particle: is it ___?","correct":false},{"text":"not / no","correct":false},{"text":"hello","correct":false},{"text":"good","correct":true}],"source":"Essential Thai (Higbie), p.23","parts":["ดี"]},{"id":"wi-38","type":"wordIntro","word":{"thai":"มา","roman":"maa","english":"come (back) — pai nǎi maa: where have you been?"},"source":"Essential Thai (Higbie), p.39"},{"id":"wi-39","type":"wordIntro","word":{"thai":"มั้ย","roman":"mái","english":"question particle: is it ___?"},"source":"Essential Thai (Higbie), p.23"},{"id":"mc-40","type":"translationChoice","thai":"ดีมั้ย","roman":"dii mái","options":[{"text":"Is it fun?","correct":false},{"text":"Hello.","correct":false},{"text":"Is it good?","correct":true},{"text":"Where are you going?","correct":false}],"source":"Essential Thai (Higbie), p.23","parts":["ดี","มั้ย"]},{"id":"so-41","type":"sentenceOrder","prompt":"Is it good?","tileUnit":"word","words":{"a":{"roman":"dii","thai":"ดี"},"b":{"roman":"mái","thai":"มั้ย"},"x0":{"thai":"หา","roman":"hǎa"},"x1":{"thai":"ไป","roman":"pai"}},"poolOrder":["b","x0","a","x1"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.23"},{"id":"sp-42","type":"speak","thai":"ดีมั้ย","roman":"dii mái","meaning":"Is it good?","source":"Essential Thai (Higbie), p.23","parts":["ดี","มั้ย"]},{"id":"wi-43","type":"wordIntro","word":{"thai":"ไม่","roman":"mâi","english":"not / no"},"source":"Essential Thai (Higbie), p.23"},{"id":"mc-44","type":"translationChoice","thai":"ไม่ดี","roman":"mâi dii","options":[{"text":"Is it good?","correct":false},{"text":"No, it's not good.","correct":true},{"text":"Where are you going?","correct":false},{"text":"Yes, it's good.","correct":false}],"source":"Essential Thai (Higbie), p.23","parts":["ไม่","ดี"]},{"id":"so-45","type":"sentenceOrder","prompt":"No, it's not good.","tileUnit":"word","words":{"a":{"roman":"mâi","thai":"ไม่"},"b":{"roman":"dii","thai":"ดี"},"x0":{"thai":"ครับ","roman":"khráp"},"x1":{"thai":"ค่ะ","roman":"khâ"}},"poolOrder":["a","x1","b","x0"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.23"},{"id":"mc-46","type":"translationChoice","thai":"ไม่","roman":"mâi","options":[{"text":"hello","correct":false},{"text":"question particle: is it ___?","correct":false},{"text":"not / no","correct":true},{"text":"good","correct":false}],"source":"Essential Thai (Higbie), p.23","parts":["ไม่"]},{"id":"rp-47","type":"reply","context":[{"speaker":"M","thai":"ไปไหนมา","parts":["ไป","ไหน","มา"],"roman":"pai nǎi maa","english":"Where have you been?"},{"speaker":"F","thai":"ไปเที่ยวมา","parts":["ไป","เที่ยว","มา"],"roman":"pai thîao maa","english":"I went out."},{"speaker":"M","thai":"ดีมั้ย","parts":["ดี","มั้ย"],"roman":"dii mái","english":"Was it good?"}],"replySpeaker":"F","thai":"ดี","roman":"dii","english":"Good.","options":[{"thai":"ไม่ดี","roman":"mâi dii","correct":false},{"thai":"สวัสดีครับ","roman":"sà-wàt-dii khráp","correct":false},{"thai":"ไปเที่ยว","roman":"pai thîao","correct":false},{"thai":"ดี","roman":"dii","correct":true}],"source":"Essential Thai (Higbie), p.23","parts":["ดี"]},{"id":"rp-49","type":"reply","context":[{"speaker":"M","thai":"สวัสดีครับ","parts":["สวัสดี","ครับ"],"roman":"sà-wàt-dii khráp","english":"Hello. (said by a man)"},{"speaker":"F","thai":"สวัสดีค่ะ","parts":["สวัสดี","ค่ะ"],"roman":"sà-wàt-dii khâ","english":"Hello. (said by a woman)"},{"speaker":"M","thai":"ไปเที่ยวมาดีมั้ย","parts":["ไป","เที่ยว","มา","ดี","มั้ย"],"roman":"pai thîao maa, dii mái","english":"Was your trip good?"}],"replySpeaker":"F","thai":"ไม่ดี","roman":"mâi dii","english":"No, it's not good.","options":[{"thai":"ดี","roman":"dii","correct":false},{"thai":"ไปเที่ยว","roman":"pai thîao","correct":false},{"thai":"ไม่ดี","roman":"mâi dii","correct":true},{"thai":"ไปไหน","roman":"pai nǎi","correct":false}],"source":"Essential Thai (Higbie), p.23","parts":["ไม่","ดี"]},{"id":"sp-50","type":"speak","thai":"ไม่ดี","roman":"mâi dii","meaning":"No, it's not good.","source":"Essential Thai (Higbie), p.23","parts":["ไม่","ดี"]},{"id":"match-51","type":"match","pairs":[{"thai":"ดี","roman":"dii","english":"good"},{"thai":"มา","roman":"maa","english":"come (back) — pai nǎi maa: where have you been?"},{"thai":"มั้ย","roman":"mái","english":"question particle: is it ___?"},{"thai":"ไม่","roman":"mâi","english":"not / no"}],"source":"Essential Thai (Higbie), p.23"}]$j$::jsonb),
  ($q$gh04$q$, $q$greetings-hello$q$, 3, $q$Eating, and going home$q$, $j$[{"id":"wi-52","type":"wordIntro","word":{"thai":"กิน","roman":"gin","english":"eat"},"source":"Essential Thai (Higbie), p.22"},{"id":"mc-56","type":"translationChoice","thai":"กิน","roman":"gin","options":[{"text":"go","correct":false},{"text":"eat","correct":true},{"text":"good","correct":false},{"text":"where","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["กิน"]},{"id":"wi-53","type":"wordIntro","word":{"thai":"ข้าว","roman":"khâao","english":"rice"},"source":"Essential Thai (Higbie), p.22"},{"id":"mc-57","type":"translationChoice","thai":"ข้าว","roman":"khâao","options":[{"text":"go out / travel around","correct":false},{"text":"rice","correct":true},{"text":"not / no","correct":false},{"text":"eat","correct":false}],"source":"Essential Thai (Higbie), p.22","parts":["ข้าว"]},{"id":"so-58","type":"sentenceOrder","prompt":"Eat. (rice/food)","tileUnit":"word","words":{"a":{"roman":"gin","thai":"กิน"},"b":{"roman":"khâao","thai":"ข้าว"},"x0":{"thai":"ครับ","roman":"khráp"},"x1":{"thai":"มา","roman":"maa"}},"poolOrder":["a","x1","x0","b"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.22"},{"id":"sp-59","type":"speak","thai":"กินข้าว","roman":"gin khâao","meaning":"eat (rice/food)","source":"Essential Thai (Higbie), p.22","parts":["กิน","ข้าว"]},{"id":"so-64","type":"sentenceOrder","prompt":"Go eat.","tileUnit":"word","words":{"a":{"roman":"pai","thai":"ไป"},"b":{"roman":"gin","thai":"กิน"},"c":{"roman":"khâao","thai":"ข้าว"},"x0":{"thai":"ไม่","roman":"mâi"},"x1":{"thai":"ครับ","roman":"khráp"}},"poolOrder":["x1","c","a","b","x0"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.22"},{"id":"wi-54","type":"wordIntro","word":{"thai":"กลับ","roman":"glàp","english":"return / go back"},"source":"Essential Thai (Higbie), p.22"},{"id":"mc-60","type":"translationChoice","thai":"กลับ","roman":"glàp","options":[{"text":"go out / travel around","corr